export function createKeyedLocks() {
  const tails = new Map<string, Promise<void>>()
  return {
    run<T>(key: string, job: () => T | Promise<T>): Promise<T> {
      const result = (tails.get(key) ?? Promise.resolve()).then(() => job())
      const tail = result.then(
