    this.held.length = 0
    this.getCurrentMode = null
    this.modeAtUnwire = undefined
    this.onPeerHeld = null
    this.onPeerHoldReleased = null
    this.onPeerHoldDropped = null
    this.shutdownSettleHandle?.()
    this.shutdownSettleHandle = null
